    port = int(sys.argv[1]) if len(sys.argv) > 1 else 8080
    handle = start_server(port)
    print(json.dumps({"port": port}))
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        handle.stop()
    return 0


if __name__ == "__main__":
    sys.exit(main())

