import argparse
import json
import logging
import sys

import shapeshift

logger = logging.getLogger("forma")


@shapeshift.record
class Invoice:
    # Campos de la factura
    number: int
    tags: list[str]


def load_invoice(payload: dict) -> Invoice:
    # Convierte el diccionario en una instancia de Invoice
    return shapeshift.Converter().build(payload, Invoice)


def dump_invoice(invoice: Invoice) -> dict:
    # Vuelve la instancia a un diccionario plano
    return shapeshift.Converter().dump(invoice)


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(description="Conversor de facturas")
    parser.add_argument("--number", type=int, default=7)
    args = parser.parse_args(argv)
    logging.basicConfig(level=logging.INFO)
    payload = {"number": args.number, "tags": ["urgente", "abril"]}
    try:
        invoice = load_invoice(payload)
    except shapeshift.BuildError as exc:
        logger.error("datos inválidos: %s", exc)
        return 1
    print(invoice)
    print(json.dumps(dump_invoice(invoice)))
    return 0


if __name__ == "__main__":
    sys.exit(main())

